/**
 * SOURCE OF TRUTH for the blog archive. Add and edit posts here.
 *
 * Nothing in the app imports this file, and nothing should: it holds every
 * article body inline, so importing it puts all 1.1MB of them in whatever
 * chunk reaches it. The build runs script/generatePostIndex.ts over it to
 * produce lib/postIndex.ts (metadata) and content/posts/*.md (bodies), and
 * the app reads those through lib/blogPosts.ts.
 */
/**
 * Attribution for a cover image sourced from someone else.
 *
 * Every licence we accept for third-party covers (CC BY, CC BY-SA) requires
 * credit and a link to the licence, so this travels with the post and is
 * rendered next to the image. Posts using original artwork omit it.
 */
export interface CoverCredit {
  /** Author as named by the source, plain text. */
  author: string;
  /** Human-readable licence, e.g. "CC BY-SA 4.0". */
  license: string;
  /** Canonical licence deed. */
  licenseUrl: string;
  /** The file's description page at the source. */
  sourceUrl: string;
}

export interface BlogPost {
  slug: string;
  title: string;
  /** First published, ISO date. Never changes once a post is live. */
  date: string;
  /**
   * Substantially rewritten on this date, ISO.
   *
   * Set it only when the article itself changed enough that a reader who
   * saw the old one would want to know: a rewrite, a correction, a section
   * added. Fixing a typo is not that. Absent means the post still says what
   * it said on the day it went up, and the schema reports dateModified as
   * the publication date.
   */
  updated?: string;
  tags: string[];
  excerpt: string;
  coverImage: string;
  coverCredit?: CoverCredit;
  draft?: boolean;
  content: string;
}

